+// Walk the candidate addresses (main first, then the warm reserve) and return
+// the first that accepts our token, together with WHY every earlier one failed.
+// The old code threw the same blanket «Ни основной, ни резервный адрес не
+// отвечает» no matter what happened, and printed it even when the reserve had
+// never been published and only one address existed - which turned a plain 401
+// (missing launch token) into a phantom network outage.
+async function firstReachableBase(bases, zt, runId) {
+  const errors = [];
+  for (let i = 0; i < bases.length; i++) {
+    if (i > 0) log('Основной адрес молчит — пробую резервный…');
+    try { await preflightHub(bases[i], zt, runId); return { base: bases[i], errors }; }
+    catch (e) { errors.push({ base: bases[i], reason: (e && e.message) || String(e) }); }
+  }
+  return { base: '', errors };
+}
+// Turn the collected per-base failures into the honest message the user sees:
+// an empty token is called out as such, a single address is never blamed on a
+// reserve that does not exist, and the actual reason is always included.
+function describeBaseFailure(bases, errors, zt) {
+  const reasons = [];
+  for (const e of errors) if (e && e.reason && reasons.indexOf(e.reason) < 0) reasons.push(e.reason);
+  const detail = reasons.join('; ') || 'нет ответа';
+  if (!String(zt || '')) {
+    return 'Нет токена запуска (zt): адрес отвечает 401. Откройте хаб тем же устройством, что запускало раннер, либо запустите хаб заново.';
+  }
+  if (bases.length > 1) return 'Ни основной, ни резервный адрес не отвечает: ' + detail;
+  return 'Адрес не отвечает: ' + detail;
+}
